CREATE TABLE wallets(user_id INTEGER PRIMARY KEY, available INTEGER NOT NULL DEFAULT 0 CHECK(available>=0), frozen INTEGER NOT NULL DEFAULT 0 CHECK(frozen>=0));
CREATE TABLE products(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, price INTEGER NOT NULL CHECK(price>0), description TEXT NOT NULL, eta TEXT NOT NULL, fields TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, position INTEGER NOT NULL, revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE drafts(id TEXT PRIMARY KEY, user_id INTEGER NOT NULL, product_id INTEGER NOT NULL REFERENCES products(id), revision INTEGER NOT NULL, data TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'editing', batch_id TEXT);
CREATE TABLE batches(id TEXT PRIMARY KEY, user_id INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE orders(id TEXT PRIMARY KEY, batch_id TEXT NOT NULL REFERENCES batches(id), user_id INTEGER NOT NULL, price INTEGER NOT NULL, snapshot TEXT NOT NULL, submission TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', reason TEXT NOT NULL DEFAULT '');
CREATE TABLE receipts(id INTEGER PRIMARY KEY AUTOINCREMENT, order_id TEXT NOT NULL REFERENCES orders(id), payload TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'staged', message_id INTEGER);
CREATE TABLE ledger(id INTEGER PRIMARY KEY, event_key TEXT NOT NULL UNIQUE, user_id INTEGER NOT NULL, available_delta INTEGER NOT NULL, frozen_delta INTEGER NOT NULL, available_after INTEGER NOT NULL, frozen_after INTEGER NOT NULL, source TEXT NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit(id INTEGER PRIMARY KEY, actor INTEGER NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE events(id INTEGER PRIMARY KEY, event_key TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, target INTEGER NOT NULL, payload TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', message_id INTEGER);
CREATE TABLE reply_links(message_id INTEGER PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id));
CREATE TABLE sessions(user_id INTEGER PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE metadata(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE processed_updates(id INTEGER PRIMARY KEY);
CREATE TABLE payments(id TEXT PRIMARY KEY, user_id INTEGER NOT NULL, amount INTEGER NOT NULL CHECK(amount>=1), currency TEXT NOT NULL DEFAULT 'USDT', merchant TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'created', url TEXT, platform_id TEXT UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX orders_batch ON orders(batch_id);
CREATE INDEX receipts_order ON receipts(order_id);
